WITH TIPO_PESO_CORRETO AS (SELECT V.CODPARC, TA.TIPO_PESO, ROW_NUMBER() OVER(PARTITION BY V.CODPARC ORDER BY V.ID DESC) as rn FROM VINCULO_PARCEIRO_TIPO V JOIN TIPO_ARMAZENAGEM TA ON V.ID_TIPO_ARMAZENAGEM = TA.ID WHERE V.CODPARC = :VAR_PARCEIRO_SELECIONADO), MOVIMENTOS_UNIFICADOS AS (SELECT G.DATA_ENTREGA AS DT_MOV, I.AUTO_ID, (CASE WHEN TPC.TIPO_PESO = 'Líquido' THEN I.PESO_ITEM_LIQ ELSE I.PESO_ITEM END) AS PESO, 'ENTRADA' AS TIPO_MOV FROM GESTAO_NOTAS_APROVACAO G JOIN IMP_ITENS_NOTAS_APRV I ON G.NUNOTA = I.NUNOTA JOIN TIPO_PESO_CORRETO TPC ON G.CODPARC = TPC.CODPARC AND TPC.rn = 1 WHERE G.CODPARC = :VAR_PARCEIRO_SELECIONADO AND G.ENTREGUE = 1 UNION ALL SELECT N.DTNEG AS DT_MOV, N.AUTO_ID, (CASE WHEN TPC.TIPO_PESO = 'Líquido' THEN N.PESO_ITEM_LIQ ELSE N.PESO_ITEM END) AS PESO, 'SAIDA' AS TIPO_MOV FROM IMP_NOTAS_ARMAZ N JOIN TIPO_PESO_CORRETO TPC ON N.CODPARC = TPC.CODPARC AND TPC.rn = 1 WHERE N.CODPARC = :VAR_PARCEIRO_SELECIONADO AND N.ATUALESTOQUE = 1), SALDO_INICIAL_VAL AS (SELECT GREATEST(IFNULL(SUM(CASE WHEN TIPO_MOV = 'ENTRADA' THEN PESO ELSE -PESO END), 0), 0) AS VALOR FROM MOVIMENTOS_UNIFICADOS WHERE DT_MOV < :VAR_PERIODO_INICIO), MOVIMENTOS_PERIODO_DETALHADO AS (SELECT DT_MOV, AUTO_ID, PESO, TIPO_MOV FROM MOVIMENTOS_UNIFICADOS WHERE DT_MOV BETWEEN :VAR_PERIODO_INICIO AND :VAR_PERIODO_FIM), SALDO_DIARIO AS (SELECT DT_MOV, (SELECT VALOR FROM SALDO_INICIAL_VAL) + SUM(CASE WHEN TIPO_MOV = 'ENTRADA' THEN PESO ELSE -PESO END) OVER (ORDER BY DT_MOV, AUTO_ID) AS SALDO_ACUMULADO FROM MOVIMENTOS_PERIODO_DETALHADO), CANDIDATOS_PICO AS (SELECT VALOR AS SALDO, :VAR_PERIODO_INICIO AS DATA_PICO, 'Saldo Inicial' as TIPO_PICO FROM SALDO_INICIAL_VAL UNION ALL SELECT SALDO_ACUMULADO, DT_MOV, 'Movimentação' as TIPO_PICO FROM SALDO_DIARIO) SELECT GREATEST(IFNULL(SALDO, 0), 0) AS PICO_PERIODO, CASE WHEN TIPO_PICO = 'Saldo Inicial' THEN 'Saldo Inicial' ELSE DATE_FORMAT(DATA_PICO, '%d/%m/%Y') END AS DATA_PICO FROM CANDIDATOS_PICO ORDER BY SALDO DESC LIMIT 1